insert into public.components (external_id, simplified, traditional, name_en, name_id, meaning_en, meaning_id, mnemonic_en, mnemonic_id, examples, order_index, tags, is_reviewable) values
  ('component_person_side', '亻', '亻', 'person side', 'orang di samping', 'person', 'orang', 'A person standing sideways — slim, upright, two legs. Spot this and think *person*.', '亻 kayak siluet *orang* berdiri dari samping — kurus, tegak, dua kaki.', array['你', '他']::text[], 1, array['common_component']::text[], false),
  ('component_mouth', '口', '口', 'mouth', 'mulut', 'mouth / opening', 'mulut / bukaan', 'A small open square — the shape of a *mouth* ready to speak.', '口 kotak kecil terbuka — persis bentuk *mulut* waktu mau ngomong.', array['吗', '喝']::text[], 2, array['common_component']::text[], false),
  ('component_woman', '女', '女', 'woman', 'perempuan', 'woman', 'perempuan', 'A *woman* sitting gracefully with folded arms — elegant and composed.', '女 kayak sosok *perempuan* duduk anggun dengan tangan terlipat.', array['好', '她']::text[], 3, array['common_component']::text[], false),
  ('component_child', '子', '子', 'child', 'anak', 'child', 'anak', 'A *child* with arms stretched wide, asking to be picked up.', '子 kayak *anak* kecil yang tangannya direntangkan minta digendong.', array['好']::text[], 4, array['common_component']::text[], false)
insert into public.hanzi (external_id, simplified, traditional, meaning_en, meaning_id, accepted_meanings_en, accepted_meanings_id, blocked_meanings_en, blocked_meanings_id, pinyin_diacritic, pinyin_numbered, pinyin_syllables, tone_number, tone_pattern, mnemonic_en, mnemonic_id, tone_mnemonic_en, tone_mnemonic_id, audio_url, examples, order_index, tags, is_reviewable) values
  ('hanzi_wo', '我', '我', 'I / me', 'aku / saya', array['I / me']::text[], array['aku / saya']::text[], array[]::text[], array[]::text[], 'wǒ', 'wo3', '[{"hanzi":"我","text":"wǒ","tone":3}]'::jsonb, 3, '3', 'A fist pressed to the chest — this is *me*, not anyone else. wǒ ≈ "woh!" like spotting yourself in the mirror. Tone 3 dips then rises, like "hmm.. oh right!"', 'Tangan mengepal, nunjuk dada sendiri — ini *aku*, bukan orang lain. wǒ ≈ "woh!" kayak kaget lihat diri sendiri di cermin. Nada 3 turun terus naik, kayak "hmm.. oh iya!"', null, null, null, array[]::text[], 1, array[]::text[], true),
  ('hanzi_ni', '你', '你', 'you', 'kamu', array['you']::text[], array['kamu']::text[], array[]::text[], array[]::text[], 'nǐ', 'ni3', '[{"hanzi":"你","text":"nǐ","tone":3}]'::jsonb, 3, '3', 'A 亻 person standing there, and you point straight at them — that''s *you*. nǐ ≈ "knee" — you''re pointing at their knee. Tone 3 dips then rises, like "hmm.. oh right!"', '亻 orang berdiri di sana, kamu nunjuk langsung ke arahnya — itu *kamu*. nǐ ≈ "nih" kayak "nih, kamu!" Nada 3 turun terus naik, kayak "hmm.. oh iya!"', null, null, null, array[]::text[], 2, array[]::text[], true),
  ('hanzi_shi', '是', '是', 'to be / is', 'adalah', array['to be / is']::text[], array['adalah']::text[], array[]::text[], array[]::text[], 'shì', 'shi4', '[{"hanzi":"是","text":"shì","tone":4}]'::jsonb, 4, '4', 'The character that declares something *is* what it is — firm and final. shì ≈ "sure!" like saying "yes, that''s it!" Tone 4 drops sharp, certain and done.', 'Ini karakter yang bilang sesuatu *adalah* apa adanya — pernyataan tegas. shì ≈ "shr!" kayak bilang "iya, itu dia!" Nada 4 turun tajam, pasti dan final.', null, null, null, array[]::text[], 3, array[]::text[], true),
  ('hanzi_you_have', '有', '有', 'have / exist', 'punya / ada', array['have / exist']::text[], array['punya / ada']::text[], array[]::text[], array[]::text[], 'yǒu', 'you3', '[{"hanzi":"有","text":"yǒu","tone":3}]'::jsonb, 3, '3', 'A hand gripping something tightly — this is mine, I *have* it. yǒu ≈ "yo!" like "yo, I''ve got it!" Tone 3 dips then rises, like finding what you were looking for.', 'Tangan megang sesuatu erat-erat — ini *punya*, ini milikku. yǒu ≈ "yo!" kayak "yo, ini ada!" Nada 3 turun terus naik, kayak nemuin sesuatu yang dicari.', null, null, null, array[]::text[], 4, array[]::text[], true),
  ('hanzi_bu', '不', '不', 'not', 'tidak', array['not']::text[], array['tidak']::text[], array[]::text[], array[]::text[], 'bù', 'bu4', '[{"hanzi":"不","text":"bù","tone":4}]'::jsonb, 4, '4', 'A hand raised, head shaking — *no*, stop right there. bù ≈ "boo!" like booing something off stage. Tone 4 drops sharp, firm and final.', 'Tangan diangkat, kepala geleng — *tidak*, jangan dilanjut. bù ≈ "bu!" kayak penolakan yang keluar langsung. Nada 4 turun tajam, tegas dan final.', null, null, null, array[]::text[], 5, array[]::text[], true),
  ('hanzi_hao', '好', '好', 'good / okay', 'baik / oke', array['good / okay']::text[], array['baik / oke']::text[], array[]::text[], array[]::text[], 'hǎo', 'hao3', '[{"hanzi":"好","text":"hǎo","tone":3}]'::jsonb, 3, '3', '女 mom watches her 子 child take their first steps — everything is *good*. hǎo ≈ "how" — how good is that! Tone 3 dips then rises, like a gasp turning into a cheer.', '女 ibu ngeliat 子 anaknya jalan pertama kali, semuanya *baik*-baik aja. hǎo ≈ "hao!" Nada 3 turun terus naik, kayak "hmm.. oh iya!"', null, null, null, array[]::text[], 6, array[]::text[], true),
  ('hanzi_qu', '去', '去', 'go', 'pergi', array['go']::text[], array['pergi']::text[], array[]::text[], array[]::text[], 'qù', 'qu4', '[{"hanzi":"去","text":"qù","tone":4}]'::jsonb, 4, '4', 'Feet moving forward, leaving the place behind — *going*. qù ≈ "choo!" like a train leaving. Tone 4 drops sharp, decision made.', 'Kaki bergerak maju, pergi meninggalkan tempat — dia *pergi*. qù ≈ "chu!" kayak langkah yang tegas keluar pintu. Nada 4 turun tajam, kayak keputusan udah bulat.', null, null, null, array[]::text[], 1, array[]::text[], true),
  ('hanzi_lai', '来', '來', 'come', 'datang', array['come']::text[], array['datang']::text[], array[]::text[], array[]::text[], 'lái', 'lai2', '[{"hanzi":"来","text":"lái","tone":2}]'::jsonb, 2, '2', 'Someone waving from a distance, walking toward you — *coming*. lái ≈ "lie" — they''re lying down coming to you. Tone 2 rises, like "are you here yet?"', 'Seseorang melambai dari jauh, mendekat ke arahmu — dia *datang*. lái ≈ "lai!" kayak panggilan "sini!" Nada 2 naik terus, kayak nanya "udah sampe?"', null, null, null, array[]::text[], 2, array[]::text[], true),
  ('hanzi_kan', '看', '看', 'look / see', 'lihat', array['look / see']::text[], array['lihat']::text[], array[]::text[], array[]::text[], 'kàn', 'kan4', '[{"hanzi":"看","text":"kàn","tone":4}]'::jsonb, 4, '4', 'A hand above the eyes, scanning the horizon — *looking*. kàn ≈ "con!" like "come on, look!" Tone 4 drops sharp, like a cue.', 'Tangan di atas mata, fokus ke satu arah — sedang *lihat*. kàn ≈ "kan!" kayak bilang "coba lihat!" Nada 4 turun tajam, kayak aba-aba.', null, null, null, array[]::text[], 3, array[]::text[], true),
  ('hanzi_xiang', '想', '想', 'want / think', 'ingin / pikir', array['want / think']::text[], array['ingin / pikir']::text[], array[]::text[], array[]::text[], 'xiǎng', 'xiang3', '[{"hanzi":"想","text":"xiǎng","tone":3}]'::jsonb, 3, '3', 'Thoughts drifting, something keeps coming back — *want* or *miss*. xiǎng ≈ "shyung" like a longing sigh. Tone 3 dips then rises, like nostalgia surfacing.', 'Pikiran melayang-layang, ada sesuatu yang terus diingat — lagi *mau* atau *kangen*. xiǎng ≈ "syang" kayak "sayang" tapi pendek. Nada 3 turun terus naik, kayak nostalgia yang tiba-tiba muncul.', null, null, null, array[]::text[], 4, array[]::text[], true),
  ('hanzi_chi', '吃', '吃', 'eat', 'makan', array['eat']::text[], array['makan']::text[], array[]::text[], array[]::text[], 'chī', 'chi1', '[{"hanzi":"吃","text":"chī","tone":1}]'::jsonb, 1, '1', '口 mouth wide open, ready to chew — time to *eat*. chī ≈ "chrrr" flat, like the sound of chewing steadily. Tone 1 high and flat.', '口 mulut terbuka lebar, siap ngunyah — waktunya *makan*. chī ≈ "chi" flat kayak suara sendok ketemu piring. Nada 1 tinggi rata, kayak suara yang stabil.', null, null, null, array[]::text[], 5, array[]::text[], true),
  ('hanzi_he', '喝', '喝', 'drink', 'minum', array['drink']::text[], array['minum']::text[], array[]::text[], array[]::text[], 'hē', 'he1', '[{"hanzi":"喝","text":"hē","tone":1}]'::jsonb, 1, '1', '口 mouth open, liquid going in — *drinking*. hē ≈ "huh" flat, like a satisfied sigh after a sip. Tone 1 high and steady.', '口 mulut terbuka, cairan masuk — lagi *minum*. hē ≈ "huh" tapi rata, kayak suara puas abis teguk air. Nada 1 tinggi rata, tenang dan pasti.', null, null, null, array[]::text[], 6, array[]::text[], true),
  ('hanzi_ma', '吗', '嗎', 'question particle', 'partikel tanya', array['question particle']::text[], array['partikel tanya']::text[], array[]::text[], array[]::text[], 'ma', 'ma0', '[{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, 0, '0', '口 mouth open, waiting for an answer — this character *asks*. ma is light at the end of a sentence, like a question hanging in the air. Tone 0 neutral and brief.', '口 mulut terbuka, nunggu jawaban — ini karakter yang *nanya*. ma ringan di ujung kalimat, kayak nada tanya yang gantung. Nada 0 netral, pendek, numpang lewat.', null, null, null, array[]::text[], 1, array[]::text[], true),
  ('hanzi_ne', '呢', '呢', 'and you / what about', 'bagaimana dengan', array['and you / what about']::text[], array['bagaimana dengan']::text[], array[]::text[], array[]::text[], 'ne', 'ne0', '[{"hanzi":"呢","text":"ne","tone":0}]'::jsonb, 0, '0', '口 mouth half open, casually tossing the question back — "*what about you*?" ne is soft at the end. Tone 0 light and easy.', '口 mulut setengah terbuka, nanya balik dengan santai — kayak "*kamu* gimana?" ne ringan di ujung, kayak lempar pertanyaan balik. Nada 0 netral dan ringan.', null, null, null, array[]::text[], 2, array[]::text[], true),
  ('hanzi_shei', '谁', '誰', 'who', 'siapa', array['who']::text[], array['siapa']::text[], array[]::text[], array[]::text[], 'shéi', 'shei2', '[{"hanzi":"谁","text":"shéi","tone":2}]'::jsonb, 2, '2', 'A 讠 voice calling out, eyes scanning the room — *who* is that? shuí ≈ "shway" like a puzzled "who?" Tone 2 rises, like the question is still unanswered.', '讠 ucapan keluar sambil mata nyari-nyari — *siapa* ini? shuí ≈ "shway" kayak nanya bingung. Nada 2 naik terus, kayak pertanyaan yang belum terjawab.', null, null, null, array[]::text[], 3, array[]::text[], true),
  ('hanzi_shen', '什', '什', 'what part', 'bagian apa', array['what part']::text[], array['bagian apa']::text[], array[]::text[], array[]::text[], 'shén', 'shen2', '[{"hanzi":"什","text":"shén","tone":2}]'::jsonb, 2, '2', 'Half of a question — meaningless alone, needs 么 to become *what*. shén ≈ "shun" rising. Tone 2 goes up, like a question hanging open.', 'Karakter setengah dari kata tanya — sendirian belum bermakna, butuh 么 untuk jadi *apa*. shén ≈ "shen" kayak "then" tapi lebih depan. Nada 2 naik, kayak pertanyaan yang menggantung.', null, null, null, array[]::text[], 4, array[]::text[], true),
  ('hanzi_me', '么', '麼', 'what suffix', 'akhiran apa', array['what suffix']::text[], array['akhiran apa']::text[], array[]::text[], array[]::text[], 'me', 'me0', '[{"hanzi":"么","text":"me","tone":0}]'::jsonb, 0, '0', '什''s loyal partner — only becomes *what* when joined as 什么. me is light, riding behind 什. Tone 0 neutral.', 'Pasangan setia 什 — dua-duanya baru jadi *apa* kalau digabung jadi 什么. me ringan, numpang di belakang 什. Nada 0 netral.', null, null, null, array[]::text[], 5, array[]::text[], true),
  ('hanzi_na', '哪', '哪', 'which / where', 'yang mana / mana', array['which / where']::text[], array['yang mana / mana']::text[], array[]::text[], array[]::text[], 'nǎ', 'na3', '[{"hanzi":"哪","text":"nǎ","tone":3}]'::jsonb, 3, '3', '口 mouth asking while pointing in no clear direction — *which* one? nǎ ≈ "nah" like "nah, which one?" Tone 3 dips then rises, like confusion becoming clarity.', '口 mulut nanya sambil nunjuk ke arah yang tidak pasti — *mana* sih? nǎ ≈ "na" kayak "nah, yang mana?" Nada 3 turun terus naik, kayak bingung lalu sadar.', null, null, null, array[]::text[], 6, array[]::text[], true),
  ('hanzi_jin', '今', '今', 'now / current', 'sekarang / saat ini', array['now / current']::text[], array['sekarang / saat ini']::text[], array[]::text[], array[]::text[], 'jīn', 'jin1', '[{"hanzi":"今","text":"jīn","tone":1}]'::jsonb, 1, '1', 'The day right in front of you, not yesterday not tomorrow — *now*, *today*. jīn ≈ "jean" flat like a steady clock. Tone 1 high and even.', 'Hari yang ada di depan mata, bukan kemarin bukan besok — *sekarang* ini. jīn ≈ "jin" flat kayak hari yang berjalan tenang. Nada 1 tinggi rata, stabil kayak jarum jam.', null, null, null, array[]::text[], 1, array[]::text[], true),
  ('hanzi_tian', '天', '天', 'day / sky', 'hari / langit', array['day / sky']::text[], array['hari / langit']::text[], array[]::text[], array[]::text[], 'tiān', 'tian1', '[{"hanzi":"天","text":"tiān","tone":1}]'::jsonb, 1, '1', 'The wide sky above — one full *day* from morning to night. tiān ≈ "tyen" flat and open. Tone 1 high and steady, like a sky that stretches.', 'Langit luas di atas — satu *hari* penuh dari pagi ke malam. tiān ≈ "tyen" flat dan luas. Nada 1 tinggi rata, kayak langit yang membentang.', null, null, null, array[]::text[], 2, array[]::text[], true),
  ('hanzi_ming', '明', '明', 'bright / tomorrow part', 'terang / bagian besok', array['bright / tomorrow part']::text[], array['terang / bagian besok']::text[], array[]::text[], array[]::text[], 'míng', 'ming2', '[{"hanzi":"明","text":"míng","tone":2}]'::jsonb, 2, '2', '日 sun + 月 moon shining together — *bright*, full of hope, like *tomorrow*. míng ≈ "ming" rising like a sunrise. Tone 2 climbs, like morning energy.', '日 matahari + 月 bulan bersinar bareng — *terang* dan penuh harapan, kayak hari *besok*. míng ≈ "ming" naik kayak matahari terbit. Nada 2 naik terus, kayak semangat pagi.', null, null, null, array[]::text[], 3, array[]::text[], true),
  ('hanzi_xian', '现', '現', 'current', 'saat ini', array['current']::text[], array['saat ini']::text[], array[]::text[], array[]::text[], 'xiàn', 'xian4', '[{"hanzi":"现","text":"xiàn","tone":4}]'::jsonb, 4, '4', 'Something appearing, real and right in front of you — *right now*, not later. xiàn ≈ "shyen!" sharp. Tone 4 drops fast, like "here it is, now!"', 'Sesuatu yang muncul dan nyata di depan mata — ini *saat ini*, bukan nanti. xiàn ≈ "syen!" tegas. Nada 4 turun tajam, kayak "ini dia, sekarang!"', null, null, null, array[]::text[], 4, array[]::text[], true),
  ('hanzi_zai_now', '在', '在', 'currently / at', 'sedang / di', array['currently / at']::text[], array['sedang / di']::text[], array[]::text[], array[]::text[], 'zài', 'zai4', '[{"hanzi":"在","text":"zài","tone":4}]'::jsonb, 4, '4', 'You''re standing at one point, right there — *currently* at that spot. zài ≈ "zai!" like confirming "yes, right here!" Tone 4 drops sharp, certain.', 'Kamu ada di satu titik, berdiri di sana — *sedang* di situ. zài ≈ "zai!" kayak konfirmasi "iya, di sini!" Nada 4 turun tajam, pasti.', null, null, null, array[]::text[], 5, array[]::text[], true),
  ('hanzi_zai', '在', '在', 'be at / in', 'berada di', array['be at / in']::text[], array['berada di']::text[], array[]::text[], array[]::text[], 'zài', 'zai4', '[{"hanzi":"在","text":"zài","tone":4}]'::jsonb, 4, '4', 'You''re standing at one point, right there — *currently* at that spot. zài ≈ "zai!" like confirming "yes, right here!" Tone 4 drops sharp, certain.', 'Kamu ada di satu titik, berdiri di sana — *sedang* di situ. zài ≈ "zai!" kayak konfirmasi "iya, di sini!" Nada 4 turun tajam, pasti.', null, null, null, array[]::text[], 1, array[]::text[], true),
  ('hanzi_li', '里', '裡', 'inside', 'di dalam', array['inside']::text[], array['di dalam']::text[], array[]::text[], array[]::text[], 'lǐ', 'li3', '[{"hanzi":"里","text":"lǐ","tone":3}]'::jsonb, 3, '3', 'Something sitting *inside* — 里 points to what''s within. lǐ ≈ "lee" dipping then rising. Tone 3 like "hmm, inside?"', 'Sesuatu ada *di dalam* — 里 kayak menunjuk bagian dalam dari sesuatu. lǐ ≈ "li" turun terus naik. Nada 3 kayak "hmm, di dalamnya ya?"', null, null, null, array[]::text[], 2, array[]::text[], true),
  ('hanzi_jia', '家', '家', 'home', 'rumah', array['home']::text[], array['rumah']::text[], array[]::text[], array[]::text[], 'jiā', 'jia1', '[{"hanzi":"家","text":"jiā","tone":1}]'::jsonb, 1, '1', 'A roof above, warmth below — that''s *home*. jiā ≈ "jya" flat and warm. Tone 1 steady, like home always being there.', 'Atap di atas, kehangatan di bawah — itulah *rumah*. jiā ≈ "jya" flat dan hangat. Nada 1 tinggi rata, kayak rumah yang selalu ada.', null, null, null, array[]::text[], 3, array[]::text[], true),
  ('hanzi_xue', '学', '學', 'study / learn', 'belajar', array['study / learn']::text[], array['belajar']::text[], array[]::text[], array[]::text[], 'xué', 'xue2', '[{"hanzi":"学","text":"xué","tone":2}]'::jsonb, 2, '2', 'Hands writing, mind focused — *studying*. xué ≈ "syueh" rising like growing curiosity. Tone 2 climbs, like wanting to know more.', 'Tangan nulis, kepala fokus — lagi *belajar*. xué ≈ "syueh" naik kayak semangat yang tumbuh. Nada 2 naik terus, kayak rasa ingin tahu.', null, null, null, array[]::text[], 4, array[]::text[], true),
  ('hanzi_xiao_school', '校', '校', 'school part', 'bagian sekolah', array['school part']::text[], array['bagian sekolah']::text[], array[]::text[], array[]::text[], 'xiào', 'xiao4', '[{"hanzi":"校","text":"xiào","tone":4}]'::jsonb, 4, '4', 'A place where people gather to learn together — that''s *school*. xiào ≈ "syow!" Tone 4 drops sharp, like a school bell ringing.', 'Tempat orang berkumpul untuk belajar bersama — itulah *sekolah*. xiào ≈ "syao!" Nada 4 turun tajam, kayak bel sekolah berbunyi.', null, null, null, array[]::text[], 5, array[]::text[], true),
  ('hanzi_hui', '回', '回', 'return', 'kembali', array['return']::text[], array['kembali']::text[], array[]::text[], array[]::text[], 'huí', 'hui2', '[{"hanzi":"回","text":"huí","tone":2}]'::jsonb, 2, '2', 'Shaped like a path that loops all the way back — *return* to where you started. huí ≈ "hway" rising like steps getting closer to home. Tone 2 goes up.', 'Bentuknya kayak jalan yang melingkar balik — *kembali* ke titik semula. huí ≈ "hway" naik kayak langkah pulang yang semakin dekat. Nada 2 naik terus.', null, null, null, array[]::text[], 6, array[]::text[], true),
  ('hanzi_mai_buy', '买', '買', 'buy', 'beli', array['buy']::text[], array['beli']::text[], array[]::text[], array[]::text[], 'mǎi', 'mai3', '[{"hanzi":"买","text":"mǎi","tone":3}]'::jsonb, 3, '3', 'A hand reaching down from a shelf, ready to take it home — going to *buy*. mǎi ≈ "my" — it''s going to be *mine*. Tone 3 dips then rises, like "hmm, I''ll take this!"', 'Tangan nurunin sesuatu dari rak, siap dibawa pulang — mau *beli*. mǎi ≈ "mai" turun terus naik. Nada 3 kayak "hmm, ini deh, aku beli!"', null, null, null, array[]::text[], 1, array[]::text[], true),
  ('hanzi_qian', '钱', '錢', 'money', 'uang', array['money']::text[], array['uang']::text[], array[]::text[], array[]::text[], 'qián', 'qian2', '[{"hanzi":"钱","text":"qián","tone":2}]'::jsonb, 2, '2', 'Metal that always changes hands — that''s *money*. qián ≈ "chyen" rising like prices always do. Tone 2 goes up.', 'Logam yang selalu berpindah tangan — itulah *uang*. qián ≈ "chyen" naik kayak harga yang terus naik. Nada 2 naik terus.', null, null, null, array[]::text[], 2, array[]::text[], true),
  ('hanzi_duo', '多', '多', 'many / much', 'banyak', array['many / much']::text[], array['banyak']::text[], array[]::text[], array[]::text[], 'duō', 'duo1', '[{"hanzi":"多","text":"duō","tone":1}]'::jsonb, 1, '1', 'Many things stacked together — this is *a lot*. duō ≈ "dwoh" flat. Tone 1 high and steady, like a stable pile.', 'Banyak hal ditumpuk jadi satu — ini *banyak*. duō ≈ "dwoh" flat. Nada 1 tinggi rata, kayak tumpukan yang stabil.', null, null, null, array[]::text[], 3, array[]::text[], true),
  ('hanzi_shao', '少', '少', 'few / little', 'sedikit', array['few / little']::text[], array['sedikit']::text[], array[]::text[], array[]::text[], 'shǎo', 'shao3', '[{"hanzi":"少","text":"shǎo","tone":3}]'::jsonb, 3, '3', 'Just a little left, almost gone — this is *a little*. shǎo ≈ "shao" dipping then rising. Tone 3 like "hmm, not much left."', 'Sedikit yang tersisa, hampir habis — ini *sedikit*. shǎo ≈ "shao" turun terus naik. Nada 3 kayak "hmm, tinggal dikit nih."', null, null, null, array[]::text[], 4, array[]::text[], true),
  ('hanzi_fan', '饭', '飯', 'rice / meal', 'nasi / makanan', array['rice / meal']::text[], array['nasi / makanan']::text[], array[]::text[], array[]::text[], 'fàn', 'fan4', '[{"hanzi":"饭","text":"fàn","tone":4}]'::jsonb, 4, '4', 'Food that''s always on the table — *rice*, the staple of every meal. fàn ≈ "fan!" Tone 4 drops sharp, like a bowl hitting the table.', '食 makanan ada di sana — *nasi*, makanan pokok yang selalu ada di meja. fàn ≈ "fan!" Nada 4 turun tajam, kayak piring nasi ditaruh di meja.', null, null, null, array[]::text[], 5, array[]::text[], true),
  ('hanzi_shui', '水', '水', 'water', 'air', array['water']::text[], array['air']::text[], array[]::text[], array[]::text[], 'shuǐ', 'shui3', '[{"hanzi":"水","text":"shuǐ","tone":3}]'::jsonb, 3, '3', 'A stream flowing continuously — that''s *water*. shuǐ ≈ "shway" dipping then rising. Tone 3 like water flowing down then back up.', 'Aliran cairan yang terus mengalir — itulah *air*. shuǐ ≈ "shway" turun terus naik. Nada 3 kayak aliran yang turun lalu naik lagi.', null, null, null, array[]::text[], 6, array[]::text[], true),
  ('hanzi_ta_he', '他', '他', 'he / him', 'dia laki-laki', array['he / him']::text[], array['dia laki-laki']::text[], array[]::text[], array[]::text[], 'tā', 'ta1', '[{"hanzi":"他","text":"tā","tone":1}]'::jsonb, 1, '1', '亻 a person — but the one being talked about, not the one talking. *He / him*. tā ≈ "ta" flat. Tone 1 neutral, like saying someone''s name.', '亻 orang, tapi yang lagi dibicarain, bukan yang ngomong — *dia* (laki-laki). tā ≈ "ta" flat. Nada 1 tinggi rata, netral kayak nyebut nama orang.', null, null, null, array[]::text[], 1, array[]::text[], true),
  ('hanzi_ta_she', '她', '她', 'she / her', 'dia perempuan', array['she / her']::text[], array['dia perempuan']::text[], array[]::text[], array[]::text[], 'tā', 'ta1', '[{"hanzi":"她","text":"tā","tone":1}]'::jsonb, 1, '1', '女 woman on the left side — *she / her*, same sound as 他, different character. tā ≈ "ta" flat. Tone 1 high and steady.', '女 perempuan di sisi kiri — *dia* (perempuan), bedanya cuma komponen kirinya. tā ≈ "ta" flat, bunyinya sama persis kayak 他. Nada 1 tinggi rata.', null, null, null, array[]::text[], 2, array[]::text[], true),
  ('hanzi_men', '们', '們', 'plural marker', 'penanda jamak', array['plural marker']::text[], array['penanda jamak']::text[], array[]::text[], array[]::text[], 'men', 'men0', '[{"hanzi":"们","text":"men","tone":0}]'::jsonb, 0, '0', 'A plural tag — stick it after any person word and it becomes *many people*. men is light and quick. Tone 0 neutral.', 'Komponen penanda jamak — tempel di belakang kata orang, langsung jadi *banyak orang*. men ringan dan pendek. Nada 0 netral.', null, null, null, array[]::text[], 3, array[]::text[], true),
  ('hanzi_peng', '朋', '朋', 'friend part', 'bagian teman', array['friend part']::text[], array['bagian teman']::text[], array[]::text[], array[]::text[], 'péng', 'peng2', '[{"hanzi":"朋","text":"péng","tone":2}]'::jsonb, 2, '2', 'Two wings flying side by side in the same direction — a *friend* always there beside you. péng ≈ "pung" rising. Tone 2 climbs, like the energy of seeing a friend.', 'Dua sayap terbang bersama ke arah yang sama — *teman* itu yang selalu ada di sisi kamu. péng ≈ "pung" naik. Nada 2 naik terus, kayak semangat ketemu teman.', null, null, null, array[]::text[], 4, array[]::text[], true),
  ('hanzi_you_friend', '友', '友', 'friend', 'teman', array['friend']::text[], array['teman']::text[], array[]::text[], array[]::text[], 'yǒu', 'you3', '[{"hanzi":"友","text":"yǒu","tone":3}]'::jsonb, 3, '3', 'Hands reaching out to help — a *friend* you can count on. yǒu ≈ "yo" dipping then rising. Tone 3 like a nod: "yeah, that''s my friend."', 'Tangan yang saling membantu — *teman* yang bisa diandalkan. yǒu ≈ "yo" turun terus naik. Nada 3 kayak anggukan "iya, ini temanku."', null, null, null, array[]::text[], 5, array[]::text[], true),
  ('hanzi_ma_mother', '妈', '媽', 'mom', 'ibu', array['mom']::text[], array['ibu']::text[], array[]::text[], array[]::text[], 'mā', 'ma1', '[{"hanzi":"妈","text":"mā","tone":1}]'::jsonb, 1, '1', '女 the most important woman in your life — *mom*. mā ≈ "ma" flat and warm. Tone 1 high and steady, like a call you''ve said a thousand times.', '女 perempuan yang paling penting dalam hidupmu — *mama*. mā ≈ "ma" flat dan hangat. Nada 1 tinggi rata, kayak panggilan yang udah hafal banget.', null, null, null, array[]::text[], 6, array[]::text[], true),
  ('hanzi_ba_father', '爸', '爸', 'dad', 'ayah', array['dad']::text[], array['ayah']::text[], array[]::text[], array[]::text[], 'bà', 'ba4', '[{"hanzi":"爸","text":"bà","tone":4}]'::jsonb, 4, '4', 'A strong upright figure watching over from above — *dad*. bà ≈ "ba!" Tone 4 drops sharp, like a father''s firm voice.', 'Sosok tegak yang selalu jaga dari atas — *papa*. bà ≈ "ba!" Nada 4 turun tajam, kayak suara bapak yang tegas.', null, null, null, array[]::text[], 7, array[]::text[], true),
  ('hanzi_da', '大', '大', 'big', 'besar', array['big']::text[], array['besar']::text[], array[]::text[], array[]::text[], 'dà', 'da4', '[{"hanzi":"大","text":"dà","tone":4}]'::jsonb, 4, '4', '人 a person spreading their arms as wide as possible — showing how *big* this is. dà ≈ "da!" Tone 4 drops sharp, like "THIS IS HUGE!"', '人 orang bentangin tangannya selebar mungkin, nunjukin betapa *besarnya* ini. dà ≈ "da!" Nada 4 turun tajam, kayak "INI GEDE!"', null, null, null, array[]::text[], 1, array[]::text[], true),
  ('hanzi_xiao', '小', '小', 'small', 'kecil', array['small']::text[], array['kecil']::text[], array[]::text[], array[]::text[], 'xiǎo', 'xiao3', '[{"hanzi":"小","text":"xiǎo","tone":3}]'::jsonb, 3, '3', 'Tiny dots scattered barely visible — this is *small*. xiǎo ≈ "syow" dipping then rising. Tone 3 like "hmm, that''s tiny."', 'Titik-titik kecil tersebar — ini *kecil*, hampir gak keliatan. xiǎo ≈ "syao" turun terus naik. Nada 3 kayak "hmm, kecil banget ya."', null, null, null, array[]::text[], 2, array[]::text[], true),
  ('hanzi_re', '热', '熱', 'hot', 'panas', array['hot']::text[], array['panas']::text[], array[]::text[], array[]::text[], 'rè', 're4', '[{"hanzi":"热","text":"rè","tone":4}]'::jsonb, 4, '4', 'Fire burning below, heat rising up — *hot*. rè ≈ "ruh!" Tone 4 drops sharp, like touching a hot pan.', 'Api menyala di bawah, panas merambat ke atas — *panas* banget. rè ≈ "ruh!" Nada 4 turun tajam, kayak nyentuh wajan panas.', null, null, null, array[]::text[], 3, array[]::text[], true),
  ('hanzi_leng', '冷', '冷', 'cold', 'dingin', array['cold']::text[], array['dingin']::text[], array[]::text[], array[]::text[], 'lěng', 'leng3', '[{"hanzi":"冷","text":"lěng","tone":3}]'::jsonb, 3, '3', 'Ice and biting wind cutting through — *cold* to the bone. lěng ≈ "lung" dipping then rising. Tone 3 like shivering then catching your breath.', 'Es dan angin dingin nusuk-nusuk — *dingin* sampai ke tulang. lěng ≈ "lung" turun terus naik. Nada 3 kayak menggigil lalu menarik napas.', null, null, null, array[]::text[], 4, array[]::text[], true),
  ('hanzi_gui', '贵', '貴', 'expensive', 'mahal', array['expensive']::text[], array['mahal']::text[], array[]::text[], array[]::text[], 'guì', 'gui4', '[{"hanzi":"贵","text":"guì","tone":4}]'::jsonb, 4, '4', '贝 a precious shell on top — shells were once currency, now it means *expensive*. guì ≈ "gway!" Tone 4 drops sharp, like shock at the price tag.', '贝 cangkang berharga di atas — dulu cangkang adalah uang, sekarang artinya *mahal*. guì ≈ "gway!" Nada 4 turun tajam, kayak kaget lihat harga.', null, null, null, array[]::text[], 5, array[]::text[], true),
  ('hanzi_pian', '便', '便', 'cheap part', 'bagian murah', array['cheap part']::text[], array['bagian murah']::text[], array[]::text[], array[]::text[], 'pián', 'pian2', '[{"hanzi":"便","text":"pián","tone":2}]'::jsonb, 2, '2', 'A character that feels light and easy — part of the word for *cheap*. pián ≈ "pyen" rising. Tone 2 lifts, like relief at an affordable price.', 'Karakter yang berasa ringan dan mudah — bagian dari kata *murah*. pián ≈ "pyen" naik. Nada 2 naik, kayak lega lihat harga terjangkau.', null, null, null, array[]::text[], 6, array[]::text[], true),
  ('hanzi_xi', '喜', '喜', 'like / happy part', 'bagian suka / senang', array['like / happy part']::text[], array['bagian suka / senang']::text[], array[]::text[], array[]::text[], 'xǐ', 'xi3', '[{"hanzi":"喜","text":"xǐ","tone":3}]'::jsonb, 3, '3', 'A smile building from the inside — that warmth turning into *like*. xǐ ≈ "she" dipping then rising. Tone 3 like a smile growing slowly.', '口 mulut senyum dari dalam — rasa senang yang meluap jadi *suka*. xǐ ≈ "shi" turun terus naik. Nada 3 kayak senyum yang tumbuh pelan.', null, null, null, array[]::text[], 1, array[]::text[], true),
  ('hanzi_huan', '欢', '歡', 'happy / like part', 'bagian suka', array['happy / like part']::text[], array['bagian suka']::text[], array[]::text[], array[]::text[], 'huān', 'huan1', '[{"hanzi":"欢","text":"huān","tone":1}]'::jsonb, 1, '1', 'People cheering and celebrating — *joyful* and enthusiastic. huān ≈ "hwan" flat. Tone 1 high and steady, like sustained cheering.', 'Orang yang lagi bersorak-sorai — *gembira* dan antusias. huān ≈ "hwan" flat. Nada 1 tinggi rata, kayak sorak yang konsisten.', null, null, null, array[]::text[], 2, array[]::text[], true),
  ('hanzi_jue', '觉', '覺', 'feel / think', 'merasa / pikir', array['feel / think']::text[], array['merasa / pikir']::text[], array[]::text[], array[]::text[], 'jué', 'jue2', '[{"hanzi":"觉","text":"jué","tone":2}]'::jsonb, 2, '2', 'Eyes just opened, becoming aware — starting to *feel* or *realize*. jué ≈ "jyueh" rising. Tone 2 climbs, like sudden awareness.', 'Mata yang baru terbuka, mulai sadar — *merasa* atau mulai *menyadari*. jué ≈ "jyueh" naik. Nada 2 naik, kayak kesadaran yang tiba-tiba muncul.', null, null, null, array[]::text[], 3, array[]::text[], true),
  ('hanzi_ke', '可', '可', 'can / okay part', 'bagian bisa / oke', array['can / okay part']::text[], array['bagian bisa / oke']::text[], array[]::text[], array[]::text[], 'kě', 'ke3', '[{"hanzi":"可","text":"kě","tone":3}]'::jsonb, 3, '3', 'A door open with nothing blocking — *can* / *may* enter. kě ≈ "kuh" dipping then rising. Tone 3 like hesitating then agreeing.', 'Pintu yang terbuka, tidak ada halangan — *boleh* masuk. kě ≈ "kuh" turun terus naik. Nada 3 kayak ragu lalu setuju.', null, null, null, array[]::text[], 4, array[]::text[], true),
  ('hanzi_yi', '以', '以', 'use / by means of', 'dengan / memakai', array['use / by means of']::text[], array['dengan / memakai']::text[], array[]::text[], array[]::text[], 'yǐ', 'yi3', '[{"hanzi":"以","text":"yǐ","tone":3}]'::jsonb, 3, '3', '可''s loyal companion — only becomes *can / may* when joined as 可以. yǐ ≈ "ee" dipping then rising. Tone 3 follows 可.', 'Pasangan setia 可 — baru lengkap jadi *boleh* kalau digabung jadi 可以. yǐ ≈ "ee" turun terus naik. Nada 3 ikut-ikutan 可.', null, null, null, array[]::text[], 5, array[]::text[], true)
insert into public.words (external_id, simplified, traditional, meaning_en, meaning_id, accepted_meanings_en, accepted_meanings_id, blocked_meanings_en, blocked_meanings_id, pinyin_diacritic, pinyin_numbered, pinyin_syllables, tone_pattern, part_of_speech, mnemonic_en, mnemonic_id, tone_note_en, tone_note_id, usage_note_en, usage_note_id, audio_url, examples, order_index, tags, is_core_word, is_reviewable) values
  ('word_wo', '我', '我', 'I / me', 'aku / saya', array['I / me']::text[], array['aku / saya']::text[], array[]::text[], array[]::text[], 'wǒ', 'wo3', '[{"hanzi":"我","text":"wǒ","tone":3}]'::jsonb, '3', 'pronoun', 'One character, one meaning — point to your own chest, that''s *me*.', 'Satu karakter, satu makna — nunjuk ke dada sendiri, itulah *aku*.', null, null, null, null, null, array[]::text[], 1, array['self']::text[], true, true),
  ('word_ni', '你', '你', 'you', 'kamu', array['you']::text[], array['kamu']::text[], array[]::text[], array[]::text[], 'nǐ', 'ni3', '[{"hanzi":"你","text":"nǐ","tone":3}]'::jsonb, '3', 'pronoun', 'One character, one person — whoever is standing in front of *you* right now.', 'Satu karakter, satu orang — yang berdiri di depan *kamu* sekarang.', null, null, null, null, null, array[]::text[], 2, array['self']::text[], true, true),
  ('word_shi', '是', '是', 'to be / is', 'adalah', array['to be / is']::text[], array['adalah']::text[], array[]::text[], array[]::text[], 'shì', 'shi4', '[{"hanzi":"是","text":"shì","tone":4}]'::jsonb, '4', 'verb', '是 is the equals sign of Mandarin — X *is* Y, clear and direct.', '是 adalah kata paling tegas untuk bilang sesuatu *adalah* sesuatu — kayak tanda sama dengan.', null, null, null, null, null, array[]::text[], 3, array['identity']::text[], true, true),
  ('word_you_have', '有', '有', 'have / there is', 'punya / ada', array['have / there is']::text[], array['punya / ada']::text[], array[]::text[], array[]::text[], 'yǒu', 'you3', '[{"hanzi":"有","text":"yǒu","tone":3}]'::jsonb, '3', 'verb', 'To *have* or to exist — 有 attaches to anything you own or anything that exists.', 'Ada atau *punya* — 有 nempel di depan apapun yang kamu miliki atau yang keberadaannya mau ditegasin.', null, null, null, null, null, array[]::text[], 4, array['basic']::text[], true, true),
  ('word_meiyou', '没有', '沒有', 'do not have / there is no', 'tidak punya / tidak ada', array['do not have / there is no']::text[], array['tidak punya / tidak ada']::text[], array[]::text[], array[]::text[], 'méi yǒu', 'mei2 you3', '[{"hanzi":"没","text":"méi","tone":2},{"hanzi":"有","text":"yǒu","tone":3}]'::jsonb, '2-3', 'verb phrase', '没 + 有 — *don''t have* / *there isn''t*. The direct opposite of 有.', '没 + 有 — *tidak ada*, kebalikan langsung dari 有. Kalau 有 itu "ada", 没有 itu "kosong".', null, null, null, null, null, array[]::text[], 5, array['basic', 'negation']::text[], true, true),
  ('word_bu', '不', '不', 'not', 'tidak', array['not']::text[], array['tidak']::text[], array[]::text[], array[]::text[], 'bù', 'bu4', '[{"hanzi":"不","text":"bù","tone":4}]'::jsonb, '4', 'negation', 'Put 不 before any word and it flips to *not* — the most used negation button.', 'Taruh 不 sebelum kata apapun, langsung jadi *tidak* — tombol negatif paling sering dipakai.', null, null, null, null, null, array[]::text[], 6, array['negation']::text[], true, true),
  ('word_hao', '好', '好', 'good / okay', 'baik / oke', array['good / okay']::text[], array['baik / oke']::text[], array[]::text[], array[]::text[], 'hǎo', 'hao3', '[{"hanzi":"好","text":"hǎo","tone":3}]'::jsonb, '3', 'adjective', '好 works as an answer, a compliment, or a greeting — all wrapped in one word: *good*.', '好 bisa jadi jawaban, pujian, atau sapaan — semua dalam satu kata *baik*.', null, null, null, null, null, array[]::text[], 7, array['basic']::text[], true, true),
  ('word_qu', '去', '去', 'go', 'pergi', array['go']::text[], array['pergi']::text[], array[]::text[], array[]::text[], 'qù', 'qu4', '[{"hanzi":"去","text":"qù","tone":4}]'::jsonb, '4', 'verb', '*Go* — one word, one direction, leaving where you are.', '*Pergi* — satu kata, satu arah, meninggalkan tempat sekarang.', null, null, null, null, null, array[]::text[], 1, array['action']::text[], true, true),
  ('word_lai', '来', '來', 'come', 'datang', array['come']::text[], array['datang']::text[], array[]::text[], array[]::text[], 'lái', 'lai2', '[{"hanzi":"来","text":"lái","tone":2}]'::jsonb, '2', 'verb', '*Come* — the opposite of 去, moving toward instead of away.', '*Datang* ke sini — kebalikan dari 去, gerakannya mendekat bukan menjauh.', null, null, null, null, null, array[]::text[], 2, array['action']::text[], true, true),
  ('word_kan', '看', '看', 'look / see', 'lihat', array['look / see']::text[], array['lihat']::text[], array[]::text[], array[]::text[], 'kàn', 'kan4', '[{"hanzi":"看","text":"kàn","tone":4}]'::jsonb, '4', 'verb', '*Look* or *watch* — 看 works for watching TV or just glancing over.', '*Lihat* atau *tonton* — 看 bisa buat nonton TV atau sekedar melirik.', null, null, null, null, null, array[]::text[], 3, array['action']::text[], true, true),
  ('word_xiang', '想', '想', 'want / think', 'ingin / pikir', array['want / think']::text[], array['ingin / pikir']::text[], array[]::text[], array[]::text[], 'xiǎng', 'xiang3', '[{"hanzi":"想","text":"xiǎng","tone":3}]'::jsonb, '3', 'verb', '*Want* or *miss* — 想 can mean craving something or missing someone.', '*Mau* atau *kangen* — 想 bisa berarti ingin sesuatu atau merindukan seseorang.', null, null, null, null, null, array[]::text[], 4, array['action']::text[], true, true),
  ('word_chi', '吃', '吃', 'eat', 'makan', array['eat']::text[], array['makan']::text[], array[]::text[], array[]::text[], 'chī', 'chi1', '[{"hanzi":"吃","text":"chī","tone":1}]'::jsonb, '1', 'verb', '*Eat* — 口 mouth is right there, because it''s all about putting food in.', '*Makan* — 口 mulut ada di sana, karena emang soal masukin makanan.', null, null, null, null, null, array[]::text[], 5, array['food']::text[], true, true),
  ('word_he', '喝', '喝', 'drink', 'minum', array['drink']::text[], array['minum']::text[], array[]::text[], array[]::text[], 'hē', 'he1', '[{"hanzi":"喝","text":"hē","tone":1}]'::jsonb, '1', 'verb', '*Drink* — same idea as 吃, 口 mouth, but this time for liquids.', '*Minum* — sama kayak 吃, ada 口 mulut, tapi kali ini untuk cairan.', null, null, null, null, null, array[]::text[], 6, array['drink']::text[], true, true),
  ('word_ma', '吗', '嗎', 'question particle', 'partikel tanya', array['question particle']::text[], array['partikel tanya']::text[], array[]::text[], array[]::text[], 'ma', 'ma0', '[{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '0', 'particle', '吗 at the end flips any statement into a question — that simple.', '吗 di ujung kalimat, pernyataan langsung jadi pertanyaan — sesimpel itu.', null, null, null, null, null, array[]::text[], 1, array['question']::text[], true, true),
  ('word_ne', '呢', '呢', 'and you / what about', 'bagaimana dengan', array['and you / what about']::text[], array['bagaimana dengan']::text[], array[]::text[], array[]::text[], 'ne', 'ne0', '[{"hanzi":"呢","text":"ne","tone":0}]'::jsonb, '0', 'particle', '呢 tosses the question back casually — "and *what about you*?"', '呢 kayak nanya balik dengan santai — "terus kamu *gimana*?"', null, null, null, null, null, array[]::text[], 2, array['question']::text[], true, true),
  ('word_shei', '谁', '誰', 'who', 'siapa', array['who']::text[], array['siapa']::text[], array[]::text[], array[]::text[], 'shéi', 'shei2', '[{"hanzi":"谁","text":"shéi","tone":2}]'::jsonb, '2', 'question word', '*Who* — one word for any question about a person.', '*Siapa* — satu kata untuk semua pertanyaan tentang orang.', null, null, null, null, null, array[]::text[], 3, array['question']::text[], true, true),
  ('word_shenme', '什么', '什麼', 'what', 'apa', array['what']::text[], array['apa']::text[], array[]::text[], array[]::text[], 'shén me', 'shen2 me0', '[{"hanzi":"什","text":"shén","tone":2},{"hanzi":"么","text":"me","tone":0}]'::jsonb, '2-0', 'question word', '*What* — 什+么 together, the most common question word in conversation.', '*Apa* — kombinasi 什+么, kata tanya paling sering muncul dalam percakapan.', null, null, null, null, null, array[]::text[], 4, array['question']::text[], true, true),
  ('word_nali', '哪里', '哪裡', 'where', 'di mana', array['where']::text[], array['di mana']::text[], array[]::text[], array[]::text[], 'nǎ lǐ', 'na3 li3', '[{"hanzi":"哪","text":"nǎ","tone":3},{"hanzi":"里","text":"lǐ","tone":3}]'::jsonb, '3-3', 'question word', '*Where* — 哪 which + 里 inside, asking about location naturally.', '*Di mana* — 哪 mana + 里 di dalam, nanya lokasi dengan natural.', null, null, null, null, null, array[]::text[], 5, array['location']::text[], true, true),
  ('word_dui', '对', '對', 'correct / right', 'benar', array['correct / right']::text[], array['benar']::text[], array[]::text[], array[]::text[], 'duì', 'dui4', '[{"hanzi":"对","text":"duì","tone":4}]'::jsonb, '4', 'adjective', '*Correct* or *right* — works as a short answer or confirmation.', '*Betul* atau *benar* — bisa jadi jawaban singkat atau konfirmasi.', null, null, null, null, null, array[]::text[], 6, array['question']::text[], true, true),
  ('word_jintian', '今天', '今天', 'today', 'hari ini', array['today']::text[], array['hari ini']::text[], array[]::text[], array[]::text[], 'jīn tiān', 'jin1 tian1', '[{"hanzi":"今","text":"jīn","tone":1},{"hanzi":"天","text":"tiān","tone":1}]'::jsonb, '1-1', 'time word', '今 now + 天 day — *today*, the day you''re actually living.', '今 sekarang + 天 hari — *hari ini*, bukan kemarin bukan besok.', null, null, null, null, null, array[]::text[], 1, array['time']::text[], true, true),
  ('word_mingtian', '明天', '明天', 'tomorrow', 'besok', array['tomorrow']::text[], array['besok']::text[], array[]::text[], array[]::text[], 'míng tiān', 'ming2 tian1', '[{"hanzi":"明","text":"míng","tone":2},{"hanzi":"天","text":"tiān","tone":1}]'::jsonb, '2-1', 'time word', '明 bright + 天 day — *tomorrow*, the bright day still ahead.', '明 terang + 天 hari — *besok*, hari yang masih terang di depan.', null, null, null, null, null, array[]::text[], 2, array['time']::text[], true, true),
  ('word_xianzai', '现在', '現在', 'now', 'sekarang', array['now']::text[], array['sekarang']::text[], array[]::text[], array[]::text[], 'xiàn zài', 'xian4 zai4', '[{"hanzi":"现","text":"xiàn","tone":4},{"hanzi":"在","text":"zài","tone":4}]'::jsonb, '4-4', 'time word', '现 appearing + 在 here — *now*, the moment that''s happening.', '现 muncul + 在 di sini — *sekarang* juga, momen yang lagi terjadi.', null, null, null, null, null, array[]::text[], 3, array['time']::text[], true, true),
  ('word_meitian', '每天', '每天', 'every day', 'setiap hari', array['every day']::text[], array['setiap hari']::text[], array[]::text[], array[]::text[], 'měi tiān', 'mei3 tian1', '[{"hanzi":"每","text":"měi","tone":3},{"hanzi":"天","text":"tiān","tone":1}]'::jsonb, '3-1', 'time word', '每 every + 天 day — *every day*, no exceptions.', '每 setiap + 天 hari — *setiap hari*, tanpa kecuali.', null, null, null, null, null, array[]::text[], 4, array['time']::text[], true, true),
  ('word_zao', '早', '早', 'early / morning', 'pagi / awal', array['early / morning']::text[], array['pagi / awal']::text[], array[]::text[], array[]::text[], 'zǎo', 'zao3', '[{"hanzi":"早","text":"zǎo","tone":3}]'::jsonb, '3', 'time word', 'The sun barely up, air still fresh — that''s *morning*.', 'Matahari baru sepenggalah, udara masih segar — inilah *pagi*.', null, null, null, null, null, array[]::text[], 5, array['time']::text[], true, true),
  ('word_zai_location', '在', '在', 'be at / in', 'berada di', array['be at / in']::text[], array['berada di']::text[], array[]::text[], array[]::text[], 'zài', 'zai4', '[{"hanzi":"在","text":"zài","tone":4}]'::jsonb, '4', 'verb/preposition', '在 marks *where* something is — put it before a location.', '在 menandai *di mana* sesuatu berada — taruh sebelum lokasi, langsung jelas posisinya.', null, null, null, null, null, array[]::text[], 1, array['location']::text[], true, true),
  ('word_zheli', '这里', '這裡', 'here', 'di sini', array['here']::text[], array['di sini']::text[], array[]::text[], array[]::text[], 'zhè lǐ', 'zhe4 li3', '[{"hanzi":"这","text":"zhè","tone":4},{"hanzi":"里","text":"lǐ","tone":3}]'::jsonb, '4-3', 'location word', '这 this + 里 inside — *here*, close to where you''re standing.', '这 ini + 里 dalam — *di sini*, lokasi yang dekat dengan pembicara.', null, null, null, null, null, array[]::text[], 2, array['location']::text[], true, true),
  ('word_nali_there', '那里', '那裡', 'there', 'di sana', array['there']::text[], array['di sana']::text[], array[]::text[], array[]::text[], 'nà lǐ', 'na4 li3', '[{"hanzi":"那","text":"nà","tone":4},{"hanzi":"里","text":"lǐ","tone":3}]'::jsonb, '4-3', 'location word', '那 that + 里 inside — *there*, further away from you.', '那 itu + 里 dalam — *di sana*, lokasi yang lebih jauh.', null, null, null, null, null, array[]::text[], 3, array['location']::text[], true, true),
  ('word_jia', '家', '家', 'home', 'rumah', array['home']::text[], array['rumah']::text[], array[]::text[], array[]::text[], 'jiā', 'jia1', '[{"hanzi":"家","text":"jiā","tone":1}]'::jsonb, '1', 'noun', 'One word for everything that feels like *home* — the place you return to.', 'Satu kata untuk semua yang terasa kayak *rumah* — tempat pulang.', null, null, null, null, null, array[]::text[], 4, array['location']::text[], true, true),
  ('word_xuexiao', '学校', '學校', 'school', 'sekolah', array['school']::text[], array['sekolah']::text[], array[]::text[], array[]::text[], 'xué xiào', 'xue2 xiao4', '[{"hanzi":"学","text":"xué","tone":2},{"hanzi":"校","text":"xiào","tone":4}]'::jsonb, '2-4', 'noun', '学 study + 校 school — *school*, the official place for learning.', '学 belajar + 校 sekolah — *sekolah*, tempat belajar yang resmi.', null, null, null, null, null, array[]::text[], 5, array['location']::text[], true, true),
  ('word_huijia', '回家', '回家', 'go home', 'pulang', array['go home']::text[], array['pulang']::text[], array[]::text[], array[]::text[], 'huí jiā', 'hui2 jia1', '[{"hanzi":"回","text":"huí","tone":2},{"hanzi":"家","text":"jiā","tone":1}]'::jsonb, '2-1', 'verb phrase', '回 return + 家 home — *go home*, the trip everyone looks forward to.', '回 kembali + 家 rumah — *pulang*, perjalanan yang selalu ditunggu.', null, null, null, null, null, array[]::text[], 6, array['movement']::text[], true, true),
  ('word_mai_buy', '买', '買', 'buy', 'beli', array['buy']::text[], array['beli']::text[], array[]::text[], array[]::text[], 'mǎi', 'mai3', '[{"hanzi":"买","text":"mǎi","tone":3}]'::jsonb, '3', 'verb', '*Buy* — the action of pulling out your wallet and getting something.', '*Beli* — aksi nurunin dompet dan nuker barang.', null, null, null, null, null, array[]::text[], 1, array['shopping']::text[], true, true),
  ('word_qian', '钱', '錢', 'money', 'uang', array['money']::text[], array['uang']::text[], array[]::text[], array[]::text[], 'qián', 'qian2', '[{"hanzi":"钱","text":"qián","tone":2}]'::jsonb, '2', 'noun', '*Money* — always moving, always needed.', '*Uang* — selalu berpindah tangan, selalu dicari.', null, null, null, null, null, array[]::text[], 2, array['shopping']::text[], true, true),
  ('word_duoshao', '多少', '多少', 'how much / how many', 'berapa', array['how much / how many']::text[], array['berapa']::text[], array[]::text[], array[]::text[], 'duō shǎo', 'duo1 shao3', '[{"hanzi":"多","text":"duō","tone":1},{"hanzi":"少","text":"shǎo","tone":3}]'::jsonb, '1-3', 'question word', '多 much + 少 little — *how much / how many*, asking the amount between the two.', '多 banyak + 少 sedikit — *berapa*, nanya jumlah di antara banyak dan sedikit.', null, null, null, null, null, array[]::text[], 3, array['shopping']::text[], true, true),
  ('word_duoshaoqian', '多少钱', '多少錢', 'how much money', 'berapa harganya', array['how much money']::text[], array['berapa harganya']::text[], array[]::text[], array[]::text[], 'duō shǎo qián', 'duo1 shao3 qian2', '[{"hanzi":"多","text":"duō","tone":1},{"hanzi":"少","text":"shǎo","tone":3},{"hanzi":"钱","text":"qián","tone":2}]'::jsonb, '1-3-2', 'question phrase', '多少 how much + 钱 money — "*how much does it cost*" — the most important phrase in any shop.', '多少 berapa + 钱 uang — "*berapa harganya*" — kalimat paling penting di toko.', null, null, null, null, null, array[]::text[], 4, array['shopping']::text[], true, true),
  ('word_fan', '饭', '飯', 'rice / meal', 'nasi / makanan', array['rice / meal']::text[], array['nasi / makanan']::text[], array[]::text[], array[]::text[], 'fàn', 'fan4', '[{"hanzi":"饭","text":"fàn","tone":4}]'::jsonb, '4', 'noun', '*Rice* or food in general — 饭 can mean both depending on context.', '*Nasi* atau makanan secara umum — 饭 bisa berarti keduanya tergantung konteks.', null, null, null, null, null, array[]::text[], 5, array['food']::text[], true, true),
  ('word_shui', '水', '水', 'water', 'air', array['water']::text[], array['air']::text[], array[]::text[], array[]::text[], 'shuǐ', 'shui3', '[{"hanzi":"水","text":"shuǐ","tone":3}]'::jsonb, '3', 'noun', '*Water* — simple, basic, always needed.', '*Air* — paling polos, paling dasar, selalu dibutuhin.', null, null, null, null, null, array[]::text[], 6, array['drink']::text[], true, true),
  ('word_ta_he', '他', '他', 'he / him', 'dia laki-laki', array['he / him']::text[], array['dia laki-laki']::text[], array[]::text[], array[]::text[], 'tā', 'ta1', '[{"hanzi":"他","text":"tā","tone":1}]'::jsonb, '1', 'pronoun', '*He / him* — the third person you''re talking about.', '*Dia* (laki-laki) — orang ketiga yang lagi dibicarain.', null, null, null, null, null, array[]::text[], 1, array['people']::text[], true, true),
  ('word_ta_she', '她', '她', 'she / her', 'dia perempuan', array['she / her']::text[], array['dia perempuan']::text[], array[]::text[], array[]::text[], 'tā', 'ta1', '[{"hanzi":"她","text":"tā","tone":1}]'::jsonb, '1', 'pronoun', '*She / her* — same pronunciation as 他, different character.', '*Dia* (perempuan) — sama bunyinya kayak 他, tapi beda tulisan.', null, null, null, null, null, array[]::text[], 2, array['people']::text[], true, true),
  ('word_women', '我们', '我們', 'we / us', 'kami / kita', array['we / us']::text[], array['kami / kita']::text[], array[]::text[], array[]::text[], 'wǒ men', 'wo3 men0', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"们","text":"men","tone":0}]'::jsonb, '3-0', 'pronoun', '我 I + 们 plural — *we / us*, depending on context.', '我 aku + 们 jamak — *kami* atau *kita*, tergantung konteks.', null, null, null, null, null, array[]::text[], 3, array['people']::text[], true, true),
  ('word_pengyou', '朋友', '朋友', 'friend', 'teman', array['friend']::text[], array['teman']::text[], array[]::text[], array[]::text[], 'péng yǒu', 'peng2 you3', '[{"hanzi":"朋","text":"péng","tone":2},{"hanzi":"友","text":"yǒu","tone":3}]'::jsonb, '2-3', 'noun', '朋 friend + 友 companion — *friend*, two characters reinforcing each other.', '朋 teman + 友 sahabat — *teman*, dua karakter yang saling nguatin maknanya.', null, null, null, null, null, array[]::text[], 4, array['people']::text[], true, true),
  ('word_mama', '妈妈', '媽媽', 'mom / mother', 'mama / ibu', array['mom / mother']::text[], array['mama / ibu']::text[], array[]::text[], array[]::text[], 'mā ma', 'ma1 ma0', '[{"hanzi":"妈","text":"mā","tone":1},{"hanzi":"妈","text":"ma","tone":0}]'::jsonb, '1-0', 'noun', '妈 repeated twice — *mom*, the most natural way to say it.', '妈 diulang dua kali — *mama*, panggilan yang paling natural.', null, null, null, null, null, array[]::text[], 5, array['family']::text[], true, true),
  ('word_baba', '爸爸', '爸爸', 'dad / father', 'papa / ayah', array['dad / father']::text[], array['papa / ayah']::text[], array[]::text[], array[]::text[], 'bà ba', 'ba4 ba0', '[{"hanzi":"爸","text":"bà","tone":4},{"hanzi":"爸","text":"ba","tone":0}]'::jsonb, '4-0', 'noun', '爸 repeated twice — *dad*, same pattern as 妈妈.', '爸 diulang dua kali — *papa*, sama polanya kayak 妈妈.', null, null, null, null, null, array[]::text[], 6, array['family']::text[], true, true),
  ('word_da', '大', '大', 'big', 'besar', array['big']::text[], array['besar']::text[], array[]::text[], array[]::text[], 'dà', 'da4', '[{"hanzi":"大","text":"dà","tone":4}]'::jsonb, '4', 'adjective', '*Big* — one word for anything large in size.', '*Besar* — satu kata yang cukup untuk semua yang ukurannya gede.', null, null, null, null, null, array[]::text[], 1, array['description']::text[], true, true),
  ('word_xiao', '小', '小', 'small', 'kecil', array['small']::text[], array['kecil']::text[], array[]::text[], array[]::text[], 'xiǎo', 'xiao3', '[{"hanzi":"小","text":"xiǎo","tone":3}]'::jsonb, '3', 'adjective', '*Small* — the direct opposite of 大.', '*Kecil* — kebalikan langsung dari 大.', null, null, null, null, null, array[]::text[], 2, array['description']::text[], true, true),
  ('word_re', '热', '熱', 'hot', 'panas', array['hot']::text[], array['panas']::text[], array[]::text[], array[]::text[], 'rè', 're4', '[{"hanzi":"热","text":"rè","tone":4}]'::jsonb, '4', 'adjective', '*Hot* — weather, food, or any situation that makes you sweat.', '*Panas* — cuaca, makanan, atau situasi yang bikin gerah.', null, null, null, null, null, array[]::text[], 3, array['description']::text[], true, true),
  ('word_leng', '冷', '冷', 'cold', 'dingin', array['cold']::text[], array['dingin']::text[], array[]::text[], array[]::text[], 'lěng', 'leng3', '[{"hanzi":"冷","text":"lěng","tone":3}]'::jsonb, '3', 'adjective', '*Cold* — the opposite of 热, weather or attitude.', '*Dingin* — kebalikan dari 热, bisa cuaca atau sikap.', null, null, null, null, null, array[]::text[], 4, array['description']::text[], true, true),
  ('word_gui', '贵', '貴', 'expensive', 'mahal', array['expensive']::text[], array['mahal']::text[], array[]::text[], array[]::text[], 'guì', 'gui4', '[{"hanzi":"贵","text":"guì","tone":4}]'::jsonb, '4', 'adjective', '*Expensive* — the price that makes your wallet cry.', '*Mahal* — harga yang bikin dompet menangis.', null, null, null, null, null, array[]::text[], 5, array['shopping']::text[], true, true),
  ('word_pianyi', '便宜', '便宜', 'cheap', 'murah', array['cheap']::text[], array['murah']::text[], array[]::text[], array[]::text[], 'pián yi', 'pian2 yi0', '[{"hanzi":"便","text":"pián","tone":2},{"hanzi":"宜","text":"yi","tone":0}]'::jsonb, '2-0', 'adjective', '便 + 宜 — *cheap*, the price that makes you smile.', '便 + 宜 — *murah*, harga yang bikin senyum sendiri.', null, null, null, null, null, array[]::text[], 6, array['shopping']::text[], true, true),
  ('word_xihuan', '喜欢', '喜歡', 'like', 'suka', array['like']::text[], array['suka']::text[], array[]::text[], array[]::text[], 'xǐ huān', 'xi3 huan1', '[{"hanzi":"喜","text":"xǐ","tone":3},{"hanzi":"欢","text":"huān","tone":1}]'::jsonb, '3-1', 'verb', '喜 like + 欢 joy — *like*, a positive feeling stronger than just okay.', '喜 suka + 欢 gembira — *suka*, perasaan positif yang lebih dari sekedar oke.', null, null, null, null, null, array[]::text[], 1, array['opinion']::text[], true, true),
  ('word_bu_xihuan', '不喜欢', '不喜歡', 'do not like', 'tidak suka', array['do not like']::text[], array['tidak suka']::text[], array[]::text[], array[]::text[], 'bù xǐ huān', 'bu4 xi3 huan1', '[{"hanzi":"不","text":"bù","tone":4},{"hanzi":"喜","text":"xǐ","tone":3},{"hanzi":"欢","text":"huān","tone":1}]'::jsonb, '4-3-1', 'verb phrase', '不 not + 喜欢 like — *don''t like*, direct and clear.', '不 tidak + 喜欢 suka — *tidak suka*, langsung dan jelas.', null, null, null, null, null, array[]::text[], 2, array['opinion']::text[], true, true),
  ('word_juede', '觉得', '覺得', 'think / feel', 'pikir / merasa', array['think / feel']::text[], array['pikir / merasa']::text[], array[]::text[], array[]::text[], 'jué de', 'jue2 de0', '[{"hanzi":"觉","text":"jué","tone":2},{"hanzi":"得","text":"de","tone":0}]'::jsonb, '2-0', 'verb', '觉 feel + 得 get — *feel* or *think*, the word for expressing opinions.', '觉 merasa + 得 dapat — *merasa* atau *berpendapat*, kata untuk ngungkapin opini.', null, null, null, null, null, array[]::text[], 3, array['opinion']::text[], true, true),
  ('word_keyi', '可以', '可以', 'can / okay', 'bisa / boleh / oke', array['can / okay']::text[], array['bisa / boleh / oke']::text[], array[]::text[], array[]::text[], 'kě yǐ', 'ke3 yi3', '[{"hanzi":"可","text":"kě","tone":3},{"hanzi":"以","text":"yǐ","tone":3}]'::jsonb, '3-3', 'modal verb', '可 can + 以 — *can / may*, permission or ability.', '可 bisa + 以 — *boleh* atau *bisa*, izin atau kemampuan.', null, null, null, null, null, array[]::text[], 4, array['opinion']::text[], true, true),
  ('word_bukeyi', '不可以', '不可以', 'cannot / not allowed', 'tidak bisa / tidak boleh', array['cannot / not allowed']::text[], array['tidak bisa / tidak boleh']::text[], array[]::text[], array[]::text[], 'bù kě yǐ', 'bu4 ke3 yi3', '[{"hanzi":"不","text":"bù","tone":4},{"hanzi":"可","text":"kě","tone":3},{"hanzi":"以","text":"yǐ","tone":3}]'::jsonb, '4-3-3', 'modal phrase', '不 not + 可以 can — *cannot / not allowed*, a firm restriction.', '不 tidak + 可以 boleh — *tidak boleh*, larangan yang tegas.', null, null, null, null, null, array[]::text[], 5, array['opinion']::text[], true, true),
  ('word_haode', '好的', '好的', 'okay / sure', 'oke / baik', array['okay / sure']::text[], array['oke / baik']::text[], array[]::text[], array[]::text[], 'hǎo de', 'hao3 de0', '[{"hanzi":"好","text":"hǎo","tone":3},{"hanzi":"的","text":"de","tone":0}]'::jsonb, '3-0', 'expression', '好 good + 的 — *okay / alright*, the most casual way to agree.', '好 baik + 的 — *oke* atau *baiklah*, jawaban setuju yang paling casual.', null, null, null, null, null, array[]::text[], 6, array['opinion']::text[], true, true)
insert into public.patterns (external_id, title_en, title_id, meaning_en, meaning_id, structure, explanation_en, explanation_id, examples, order_index, tags, is_reviewable) values
  ('pattern_a_shi_b', 'A 是 B', 'A 是 B', 'A is B', 'A adalah B', 'Subject + 是 + noun', 'Use 是 to say identity or category.', 'Gunakan 是 untuk identitas atau kategori.', '[]'::jsonb, 1, array[]::text[], false),
  ('pattern_subject_verb', 'Subject + verb', 'Subjek + kata kerja', 'simple action sentence', 'kalimat aksi sederhana', 'Subject + verb', 'Mandarin can make simple action sentences without am/is/are.', 'Mandarin bisa membuat kalimat aksi sederhana tanpa am/is/are.', '[]'::jsonb, 1, array[]::text[], false),
  ('pattern_yes_no_ma', 'Statement + 吗?', 'Pernyataan + 吗?', 'yes/no question', 'pertanyaan ya/tidak', 'Statement + 吗?', 'Add 吗 to make a yes/no question.', 'Tambahkan 吗 untuk membuat pertanyaan ya/tidak.', '[]'::jsonb, 1, array[]::text[], false),
  ('pattern_time_first', 'Time + action', 'Waktu + aksi', 'time before action', 'waktu sebelum aksi', 'Time + subject + verb', 'Put simple time words before the action.', 'Letakkan kata waktu sederhana sebelum aksi.', '[]'::jsonb, 1, array[]::text[], false),
  ('pattern_location_zai', '在 + location', '在 + lokasi', 'being at a place', 'berada di suatu tempat', 'Subject + 在 + place', 'Use 在 to say where someone or something is.', 'Gunakan 在 untuk menyatakan lokasi.', '[]'::jsonb, 1, array[]::text[], false),
  ('pattern_duoshaoqian', '多少钱?', '多少钱?', 'asking price', 'bertanya harga', 'Item + 多少钱?', 'Use 多少钱 to ask how much something costs.', 'Gunakan 多少钱 untuk bertanya harga.', '[]'::jsonb, 1, array[]::text[], false),
  ('pattern_de_possession', '的 for possession', '的 untuk kepemilikan', 'possession', 'kepemilikan', 'Person + 的 + noun', 'Use 的 to connect a person with something they have or relate to.', 'Gunakan 的 untuk menghubungkan orang dengan sesuatu yang dimiliki/terkait.', '[]'::jsonb, 1, array[]::text[], false),
  ('pattern_hen_adjective', '很 + adjective', '很 + kata sifat', 'describing with adjectives', 'mendeskripsikan dengan kata sifat', 'Subject + 很 + adjective', 'Use 很 before many simple adjectives.', 'Gunakan 很 sebelum banyak kata sifat sederhana.', '[]'::jsonb, 1, array[]::text[], false),
  ('pattern_like_object', '喜欢 + object', '喜欢 + objek', 'saying likes', 'menyatakan suka', 'Subject + 喜欢 + thing/action', 'Use 喜欢 to say what you like.', 'Gunakan 喜欢 untuk mengatakan yang kamu suka.', '[]'::jsonb, 1, array[]::text[], false)
insert into public.sentences (external_id, simplified, traditional, meaning_en, meaning_id, literal_meaning_en, literal_meaning_id, pinyin_diacritic, pinyin_numbered, pinyin_syllables, tone_pattern, notes_en, notes_id, audio_url, order_index, tags, is_reviewable) values
  ('sentence_wo_shi_wo', '我是我。', '我是我。', 'I am me.', 'Saya adalah saya.', null, null, 'wǒ shì wǒ', 'wo3 shi4 wo3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"是","text":"shì","tone":4},{"hanzi":"我","text":"wǒ","tone":3}]'::jsonb, '3-4-3', null, null, null, 1, array[]::text[], true),
  ('sentence_wo_you', '我有。', '我有。', 'I have it.', 'Saya punya.', null, null, 'wǒ yǒu', 'wo3 you3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"有","text":"yǒu","tone":3}]'::jsonb, '3-3', null, null, null, 2, array[]::text[], true),
  ('sentence_wo_qu', '我去。', '我去。', 'I’m going.', 'Saya pergi.', null, null, 'wǒ qù', 'wo3 qu4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"去","text":"qù","tone":4}]'::jsonb, '3-4', null, null, null, 1, array[]::text[], true),
  ('sentence_wo_xiang_qu', '我想去。', '我想去。', 'I want to go.', 'Saya ingin pergi.', null, null, 'wǒ xiǎng qù', 'wo3 xiang3 qu4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"想","text":"xiǎng","tone":3},{"hanzi":"去","text":"qù","tone":4}]'::jsonb, '3-3-4', null, null, null, 2, array[]::text[], true),
  ('sentence_ni_qu_ma', '你去吗？', '你去嗎？', 'Are you going?', 'Kamu pergi?', null, null, 'nǐ qù ma', 'ni3 qu4 ma0', '[{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"去","text":"qù","tone":4},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '3-4-0', null, null, null, 1, array[]::text[], true),
  ('sentence_ni_shi_shei', '你是谁？', '你是誰？', 'Who are you?', 'Kamu siapa?', null, null, 'nǐ shì shéi', 'ni3 shi4 shei2', '[{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"是","text":"shì","tone":4},{"hanzi":"谁","text":"shéi","tone":2}]'::jsonb, '3-4-2', null, null, null, 2, array[]::text[], true),
  ('sentence_jintian_wo_qu', '今天我去。', '今天我去。', 'Today I’m going.', 'Hari ini saya pergi.', null, null, 'jīn tiān wǒ qù', 'jin1 tian1 wo3 qu4', '[{"hanzi":"今","text":"jīn","tone":1},{"hanzi":"天","text":"tiān","tone":1},{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"去","text":"qù","tone":4}]'::jsonb, '1-1-3-4', null, null, null, 1, array[]::text[], true),
  ('sentence_xianzai_wo_kan', '现在我看。', '現在我看。', 'Now I watch.', 'Sekarang saya lihat.', null, null, 'xiàn zài wǒ kàn', 'xian4 zai4 wo3 kan4', '[{"hanzi":"现","text":"xiàn","tone":4},{"hanzi":"在","text":"zài","tone":4},{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"看","text":"kàn","tone":4}]'::jsonb, '4-4-3-4', null, null, null, 2, array[]::text[], true),
  ('sentence_wo_zai_jia', '我在家。', '我在家。', 'I’m at home.', 'Saya di rumah.', null, null, 'wǒ zài jiā', 'wo3 zai4 jia1', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"在","text":"zài","tone":4},{"hanzi":"家","text":"jiā","tone":1}]'::jsonb, '3-4-1', null, null, null, 1, array[]::text[], true),
  ('sentence_wo_qu_xuexiao', '我去学校。', '我去學校。', 'I go to school.', 'Saya pergi ke sekolah.', null, null, 'wǒ qù xué xiào', 'wo3 qu4 xue2 xiao4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"去","text":"qù","tone":4},{"hanzi":"学","text":"xué","tone":2},{"hanzi":"校","text":"xiào","tone":4}]'::jsonb, '3-4-2-4', null, null, null, 2, array[]::text[], true),
  ('sentence_wo_yao_shui', '我要水。', '我要水。', 'I want water.', 'Saya mau air.', null, null, 'wǒ yào shuǐ', 'wo3 yao4 shui3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"要","text":"yào","tone":4},{"hanzi":"水","text":"shuǐ","tone":3}]'::jsonb, '3-4-3', null, null, null, 1, array[]::text[], true),
  ('sentence_duoshaoqian', '多少钱？', '多少錢？', 'How much is it?', 'Berapa harganya?', null, null, 'duō shǎo qián', 'duo1 shao3 qian2', '[{"hanzi":"多","text":"duō","tone":1},{"hanzi":"少","text":"shǎo","tone":3},{"hanzi":"钱","text":"qián","tone":2}]'::jsonb, '1-3-2', null, null, null, 2, array[]::text[], true),
  ('sentence_ta_shi_pengyou', '他是朋友。', '他是朋友。', 'He is a friend.', 'Dia teman.', null, null, 'tā shì péng yǒu', 'ta1 shi4 peng2 you3', '[{"hanzi":"他","text":"tā","tone":1},{"hanzi":"是","text":"shì","tone":4},{"hanzi":"朋","text":"péng","tone":2},{"hanzi":"友","text":"yǒu","tone":3}]'::jsonb, '1-4-2-3', null, null, null, 1, array[]::text[], true),
  ('sentence_women_shi_jiaren', '我们是家人。', '我們是家人。', 'We are family.', 'Kami/kita keluarga.', null, null, 'wǒ men shì jiā rén', 'wo3 men0 shi4 jia1 ren2', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"们","text":"men","tone":0},{"hanzi":"是","text":"shì","tone":4},{"hanzi":"家","text":"jiā","tone":1},{"hanzi":"人","text":"rén","tone":2}]'::jsonb, '3-0-4-1-2', null, null, null, 2, array[]::text[], true),
  ('sentence_hen_da', '很大。', '很大。', 'Very big / quite big.', 'Besar.', null, null, 'hěn dà', 'hen3 da4', '[{"hanzi":"很","text":"hěn","tone":3},{"hanzi":"大","text":"dà","tone":4}]'::jsonb, '3-4', null, null, null, 1, array[]::text[], true),
  ('sentence_zhe_hen_gui', '这很贵。', '這很貴。', 'This is expensive.', 'Ini mahal.', null, null, 'zhè hěn guì', 'zhe4 hen3 gui4', '[{"hanzi":"这","text":"zhè","tone":4},{"hanzi":"很","text":"hěn","tone":3},{"hanzi":"贵","text":"guì","tone":4}]'::jsonb, '4-3-4', null, null, null, 2, array[]::text[], true),
  ('sentence_wo_xihuan_shui', '我喜欢水。', '我喜歡水。', 'I like water.', 'Saya suka air.', null, null, 'wǒ xǐ huān shuǐ', 'wo3 xi3 huan1 shui3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"喜","text":"xǐ","tone":3},{"hanzi":"欢","text":"huān","tone":1},{"hanzi":"水","text":"shuǐ","tone":3}]'::jsonb, '3-3-1-3', null, null, null, 1, array[]::text[], true),
  ('sentence_wo_juede_keyi', '我觉得可以。', '我覺得可以。', 'I think it’s okay.', 'Menurut saya boleh/oke.', null, null, 'wǒ jué de kě yǐ', 'wo3 jue2 de0 ke3 yi3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"觉","text":"jué","tone":2},{"hanzi":"得","text":"de","tone":0},{"hanzi":"可","text":"kě","tone":3},{"hanzi":"以","text":"yǐ","tone":3}]'::jsonb, '3-2-0-3-3', null, null, null, 2, array[]::text[], true)
insert into public.intro_cards (pack_id, external_id, title_en, title_id, body_en, body_id, example, order_index) values
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_001_what_is_mandarin', 'What is Mandarin?', 'Apa itu Mandarin?', 'Mandarin is built from sounds, tones, and characters.', 'Mandarin terdiri dari bunyi, nada, dan karakter.', null, 1),
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_002_pinyin', 'Pinyin', 'Pinyin', 'Pinyin helps you read Mandarin pronunciation using Latin letters.', 'Pinyin membantu kamu membaca pelafalan Mandarin dengan huruf Latin.', '{"simplified":"你好","traditional":"你好","pinyin":"nǐ hǎo","meaning":"hello","meaning_id":"halo"}'::jsonb, 2),
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_003_tones', 'Tones', 'Nada', 'Mandarin uses tones. The same sound can mean different things if the tone changes.', 'Mandarin memakai nada. Bunyi yang sama bisa punya arti berbeda kalau nadanya berubah.', '{"pinyin":["mā","má","mǎ","mà","ma"],"tones":[1,2,3,4,0]}'::jsonb, 3),
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_004_tone_sandhi', 'Tone sandhi', 'Tone sandhi', 'Sometimes tones shift in natural speech. The app will point this out when it matters.', 'Kadang nada berubah saat diucapkan natural. App ini akan memberi catatan saat hal itu penting.', '{"written":"nǐ hǎo = 3-3","spoken_note":"often sounds closer to 2-3"}'::jsonb, 4),
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_005_hanzi', 'Hanzi', 'Hanzi', 'Hanzi are Mandarin characters. Some are built from smaller components.', 'Hanzi adalah karakter Mandarin. Beberapa tersusun dari komponen kecil.', '{"simplified":"好","components":["女","子"],"meaning":"good"}'::jsonb, 5),
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_006_app_flow', 'How this app works', 'Cara kerja app ini', 'Short lessons, quick practice, reviews, and unlocks help you build Mandarin step by step.', 'Pelajaran singkat, latihan cepat, review, dan unlock membantu kamu belajar bertahap.', null, 6)
